el.querySelectorAll('.agent-opt').forEach(function(n){n.onclick=function(){var id=n.dataset.agent;if(id==='extra'&&!isSubActive()){closeAgents();openSubscription();return}state.agent=id;updateAgentLabel();closeAgents()}});
